<?php

use Symfony\Component\Finder\Finder;

/**
 * @return array<string, array<string, string>> files (relative to the project root) that may hold an HTML sink, with the reason for each pattern
 */
function htmlSinkAllowList(): array
{
    return [
        'resources/views/pages/settings/⚡two-factor.blade.php' => [
            'raw-echo' => 'QR code SVG generated by Fortify, no user data',
        ],
        'app/Services/Segments/SegmentConditionDescriber.php' => [
            'html-string' => 'every piece escaped with e() / highlight(); XssRenderingTest',
        ],
        'app/Filament/Resources/Segments/Schemas/SegmentInfolist.php' => [
            'html-string' => 'rule names through e(), conditions from SegmentConditionDescriber; XssRenderingTest',
            'html-method' => 'rule names through e(), conditions from SegmentConditionDescriber; XssRenderingTest',
        ],
        'resources/views/vendor/flowforge/livewire/card.blade.php' => [
            'js-attribute-echo' => '$cardAction is an action name from code; x-sortable-item gets the integer deal id; the wire:click record id goes through @js; vendor copy kept close to upstream',
        ],
        'resources/views/vendor/flowforge/livewire/column.blade.php' => [
            'js-attribute-echo' => '$isOpen is built with json_encode of the column id; the column id is a pipeline stage id from code (Column::make((string) $stage->getKey())); vendor copy kept close to upstream',
        ],
        'resources/views/components/action-message.blade.php' => [
            'js-attribute-echo' => '$on is an event-name literal passed by the calling view',
        ],
    ];
}

/**
 * @return array<string, string> the regular expression of each HTML sink pattern that applies to PHP and Blade files
 */
function htmlSinkPatterns(): array
{
    return [
        'raw-echo' => '/\{!!/',
        'html-string' => '/\bnew\s+HtmlString\s*\(/',
        'html-method' => '/->\s*html\s*\(/',
        'allow-html' => '/->\s*allowHtml\s*\(/',
        'markdown' => '/(?:->|::)\s*(?:inline)?markdown\s*\(/i',
        'tooltip-html' => '/x-tooltip\.html/',
        'x-html' => '/\bx-html\s*=/',
    ];
}

/**
 * @return string the regular expression of a user value echoed inside an attribute that Livewire or Alpine evaluates as JavaScript (`wire:*`, `x-*`, `@*`, `:*`), double- or single-quoted
 */
function htmlSinkJsAttributePattern(): string
{
    return '/\s(?:wire:(?!key\b|model\b|model\.|target\b|loading\b|loading\.|ignore\b|navigate\b|transition\b|replace\b|dirty\b|offline\b)[\w.:-]+|x-[\w.:-]+|@[\w.:-]+|:[\w.:-]+)\s*=\s*(?:"[^"]*|\'[^\']*)\{\{/';
}

/**
 * @return array<int, array{line: int, pattern: string}> the HTML sinks of a source; the JavaScript attribute pattern only applies to views
 */
function htmlSinkHitsInCode(string $code, bool $isView): array
{
    $patterns = htmlSinkPatterns();

    if ($isView) {
        $patterns['js-attribute-echo'] = htmlSinkJsAttributePattern();
    }

    $hits = [];

    foreach ($patterns as $name => $regex) {
        preg_match_all($regex, $code, $matches, PREG_OFFSET_CAPTURE);

        foreach ($matches[0] as [$text, $offset]) {
            $hits[] = ['line' => substr_count($code, "\n", 0, $offset) + 1, 'pattern' => $name];
        }
    }

    usort($hits, fn (array $a, array $b): int => [$a['line'], $a['pattern']] <=> [$b['line'], $b['pattern']]);

    return $hits;
}

/**
 * @return array<string, array<int, array{line: int, pattern: string}>> HTML sinks of `app/` and `resources/views/`, by path relative to the project root
 */
function htmlSinkHits(): array
{
    $root = dirname(__DIR__, 2);
    $hits = [];

    foreach (['app' => false, 'resources/views' => true] as $directory => $isView) {
        foreach ((new Finder)->files()->in("{$root}/{$directory}")->name('*.php') as $file) {
            $found = htmlSinkHitsInCode($file->getContents(), $isView);

            if ($found !== []) {
                $hits["{$directory}/".str_replace(DIRECTORY_SEPARATOR, '/', $file->getRelativePathname())] = $found;
            }
        }
    }

    ksort($hits);

    return $hits;
}

test('every HTML sink is allow-listed with a reason', function () {
    $allowList = htmlSinkAllowList();
    $problems = [];

    foreach (htmlSinkHits() as $path => $hits) {
        foreach ($hits as $hit) {
            if (trim($allowList[$path][$hit['pattern']] ?? '') === '') {
                $problems[] = "{$path}:{$hit['line']} → {$hit['pattern']}";
            }
        }
    }

    expect($problems)->toBe([], 'HTML sinks outside the allow-list. Escape user text with e() / {{ }}, pass values to JS with @js(), then add the file to the allow-list with the reason:'."\n".implode("\n", $problems));
});

test('the HTML sink allow-list has no stale entry', function () {
    $hits = htmlSinkHits();
    $stale = [];

    foreach (htmlSinkAllowList() as $path => $patterns) {
        foreach ($patterns as $pattern => $reason) {
            $found = collect($hits[$path] ?? [])->contains(fn (array $hit): bool => $hit['pattern'] === $pattern);

            if (trim($reason) === '' || ! $found) {
                $stale[] = "{$path} → {$pattern}";
            }
        }
    }

    expect($stale)->toBe([], 'Allow-list entries without a matching sink (or without a reason): remove them.');
});

test('the HTML sink scanner finds a new sink', function (string $code, string $pattern, bool $isView) {
    expect(array_column(htmlSinkHitsInCode($code, $isView), 'pattern'))->toBe([$pattern]);
})->with([
    'raw echo' => ['{!! $record->name !!}', 'raw-echo', true],
    'html string' => ['<?php return new HtmlString($name);', 'html-string', false],
    'html method' => ['<?php TextColumn::make(\'name\')->html();', 'html-method', false],
    'allow html' => ['<?php Select::make(\'a\')->allowHtml();', 'allow-html', false],
    'static markdown' => ['<?php Str::markdown($notes);', 'markdown', false],
    'markdown entry' => ['<?php TextEntry::make(\'notes\')->markdown();', 'markdown', false],
    'tooltip html' => ['<span x-tooltip.html="tip">', 'tooltip-html', true],
    'x-html' => ['<div x-html="notes">', 'x-html', true],
    'wire click' => ['<button wire:click="go(\'{{ $id }}\')">', 'js-attribute-echo', true],
    'x-on click' => ['<button x-on:click="go(\'{{ $id }}\')">', 'js-attribute-echo', true],
    'at click' => ['<button @click="go(\'{{ $id }}\')">', 'js-attribute-echo', true],
    'x-data' => ['<div x-data="{ id: \'{{ $id }}\' }">', 'js-attribute-echo', true],
    'alpine shorthand href' => ['<a :href="\'{{ $url }}\'">', 'js-attribute-echo', true],
    'alpine shorthand class' => ['<div :class="{ active: \'{{ $v }}\' }">', 'js-attribute-echo', true],
    'x-bind href' => ['<a x-bind:href="\'{{ $url }}\'">', 'js-attribute-echo', true],
    'single-quoted x-data' => ['<div x-data=\'{ id: "{{ $id }}" }\'>', 'js-attribute-echo', true],
    'single-quoted wire click' => ['<button wire:click=\'go("{{ $id }}")\'>', 'js-attribute-echo', true],
    'single-quoted shorthand' => ['<span :title=\'"{{ $t }}"\'>', 'js-attribute-echo', true],
]);

test('the HTML sink scanner reports the line and ignores safe code', function (string $code) {
    expect(htmlSinkHitsInCode($code, true))->toBe([]);
})->with([
    'wire key' => ['<div wire:key="rule-{{ $rule->id }}">'],
    'wire model' => ['<input wire:model="data.{{ $key }}">'],
    'plain attribute and echo' => ['<p class="{{ $class }}">{{ $name }}</p>'],
    'js helper' => ['<button wire:click="go(@js($id))">'],
    'component prop' => ['<x-filament::badge :color="$record->status->getColor()">'],
    'shorthand with js helper' => ['<a :href="@js($url)">'],
    'single-quoted plain attribute' => ['<p class=\'{{ $class }}\'>'],
    'single-quoted wire key' => ['<div wire:key=\'row-{{ $id }}\'>'],
    'ternary in an echo' => ['<span>{{ $open ? \'yes\' : \'no\' }}</span>'],
    'toHtml' => ['$html->toHtml();'],
    'named markdown argument' => ["markdown: 'emails.organization-invitation',"],
]);

test('the HTML sink scanner gives the line of a hit', function () {
    expect(htmlSinkHitsInCode("<div>\n<p>ok</p>\n{!! \$x !!}\n", true))->toBe([['line' => 3, 'pattern' => 'raw-echo']]);
});
